window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b9aab2dc98ed3c4"]={"versions": [{"id": "FIG-8b9aab2dc98ed3c4", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objekt-/Klassendiagramm zur Definition des Konfigurations-Metamodells (ECU Configuration Parameter Definition) des AUTOSAR CAN-Treibers (<code>Can : ModuleDef</code>). Es spezifiziert die strukturelle Zusammensetzung und Aggregation des globalen Konfigurationscontainers <code>CanGeneral</code> sowie seiner Parameterdefinitionen innerhalb des AUTOSAR-Basissoftware-Stacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Can : ModuleDef</code></strong>: Wurzel-Moduldefinition (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>), enthält per Komposition (<code>+container</code>) genau eine Instanz von <code>CanGeneral</code>.</li>\n<li><strong><code>CanGeneral : ParamConfContainerDef</code></strong>: Zentraler Konfigurationscontainer (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>), aggregiert über Kompositionsbeziehungen (<code>+parameter</code>) folgende Parameter:</li>\n<li><code>CanDevErrorDetection : BooleanParamDef</code>: Aktivierung der Erkennung von Entwicklungsfehlern.</li>\n<li><code>CanMultiplexedTransmission : BooleanParamDef</code>: Konfiguration gemultiplexter Übertragung.</li>\n<li><code>CanWakeupSupport : BooleanParamDef</code>: Konfiguration der Wakeup-Unterstützung.</li>\n<li><code>CanIndex : IntegerParamDef</code>: Index des CAN-Treibers.</li>\n<li><code>CanTimeoutDurationFactor : IntegerParamDef</code>: Skalierungsfaktor für Timeout-Zeiten.</li>\n<li><code>CanHardwareCancellation : BooleanParamDef</code>: Unterstützung hardwarebasierter Sendeabbrüche.</li>\n<li><code>CanVersionInfoApi : BooleanParamDef</code>: Bereitstellung der Versionsabfrage-API.</li>\n<li><code>CanMainFunctionReadPeriod : FloatParamDef</code>: Zykluszeit für Leseoperationen.</li>\n<li><code>CanMainFunctionWritePeriod : FloatParamDef</code>: Zykluszeit für Schreiboperationen.</li>\n<li><code>CanMainFunctionBusoffPeriod : FloatParamDef</code>: Zykluszeit für das Bus-Off-Handling.</li>\n<li><code>CanMainFunctionWakeupPeriod : FloatParamDef</code>: Zykluszeit für das Wakeup-Handling.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell für die Konfiguration beinhaltet das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Die parametrierten Zeitintervalle (<code>CanMainFunctionReadPeriod</code>, <code>CanMainFunctionWritePeriod</code>, <code>CanMainFunctionBusoffPeriod</code>, <code>CanMainFunctionWakeupPeriod</code>) bestimmen jedoch die periodischen Aufrufe der entsprechenden zyklischen Main-Functions des Treibers durch das BSW-Scheduling (OS/SchM).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Festlegungen definieren verbindliche Vorgaben für Konfigurationsgeneratoren und XML-Deskriptoren (BSW Module Description):</p>\n<ul class=\"fig-list\">\n<li><code>CanGeneral</code> ist als Pflichtcontainer mit exakt einfacher Multiplizität (<code>1..1</code>) an die Moduldefinition gebunden.</li>\n<li>Sämtliche Parameter sind typstreng als <code>BooleanParamDef</code>, <code>IntegerParamDef</code> oder <code>FloatParamDef</code> spezifiziert.</li>\n<li>Fehlen explizite Multiplizitätsangaben an den Parametern, gilt die metamodellierte Standardmultiplizität der BSW-Parameterdefinition (üblicherweise 1..1).</li>\n</ul>"}, {"id": "FIG-bf0f50958e573c82", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objekt-/Klassendiagramm zur Definition des Konfigurations-Metamodells (ECU Configuration Parameter Definition) des AUTOSAR CAN-Treibers (<code>Can : ModuleDef</code>). Es spezifiziert die strukturelle Zusammensetzung und Aggregation des globalen Konfigurationscontainers <code>CanGeneral</code> sowie seiner Parameterdefinitionen innerhalb des AUTOSAR-Basissoftware-Stacks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Can : ModuleDef</code></strong>: Moduldefinition (<code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 0</code>), enthält per Komposition (<code>+container</code>) den Container <code>CanGeneral</code>.</li>\n<li><strong><code>CanGeneral : ParamConfContainerDef</code></strong>: Konfigurationscontainer (<code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 1</code>), aggregiert per <code>+parameter</code>:</li>\n<li><code>CanDevErrorDetection : BooleanParamDef</code></li>\n<li><code>CanMultiplexedTransmission : BooleanParamDef</code></li>\n<li><code>CanWakeupSupport : BooleanParamDef</code></li>\n<li><code>CanMainFunctionBusoffPeriod : FloatParamDef</code></li>\n<li><code>CanMainFunctionWakeupPeriod : FloatParamDef</code></li>\n<li><code>CanLPduReceiveCalloutFunction : FunctionNameDef</code>: Konfiguration einer Callout-Funktion beim L-PDU-Empfang (<code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 0</code>).</li>\n<li><code>CanIndex : IntegerParamDef</code></li>\n<li><code>CanTimeoutDurationFactor : IntegerParamDef</code></li>\n<li><code>CanHardwareCancellation : BooleanParamDef</code></li>\n<li><code>CanVersionInfoApi : BooleanParamDef</code></li>\n<li><code>CanMainFunctionReadPeriod : FloatParamDef</code>: Zykluszeit für Leseoperationen (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).</li>\n<li><code>CanMainFunctionWritePeriod : FloatParamDef</code>: Zykluszeit für Schreiboperationen (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).</li>\n<li>Ergänzende Referenzen und Ziel-Container:</li>\n<li><code>CanMainFunctionReadPeriodRef : ReferenceParamDef</code>: Referenzparameter (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), aggregiert über <code>+reference</code> an <code>CanGeneral</code>.</li>\n<li><code>CanMainFunctionWritePeriodRef : ReferenceParamDef</code>: Referenzparameter (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>), aggregiert über <code>+reference</code> an <code>CanGeneral</code>.</li>\n<li>Beide Referenzparameter verweisen per Assoziation (<code>+destination</code>) auf den Ziel-Container <code>CanHardwareObject : ParamConfContainerDef</code> (<code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell für die Konfiguration beinhaltet das Diagramm keine Laufzeitsequenzen oder dynamischen Zustandsübergänge. Die parametrierten Zeitintervalle (<code>CanMainFunctionReadPeriod</code>, <code>CanMainFunctionWritePeriod</code>, <code>CanMainFunctionBusoffPeriod</code>, <code>CanMainFunctionWakeupPeriod</code>) bestimmen jedoch die periodischen Aufrufe der entsprechenden zyklischen Main-Functions des Treibers durch das BSW-Scheduling (OS/SchM).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für Werkzeughersteller und BSW-Konfiguration:</p>\n<ul class=\"fig-list\">\n<li><code>CanLPduReceiveCalloutFunction</code> ist optional (<code>0..1</code>) als Funktionsname (<code>FunctionNameDef</code>) konfigurierbar.</li>\n<li>Die Periodenparameter <code>CanMainFunctionReadPeriod</code> und <code>CanMainFunctionWritePeriod</code> können mehrfach bzw. nullmal auftreten (<code>0..*</code>), um multiple Lese- und Schreibzyklen zu unterstützen.</li>\n<li><code>CanMainFunctionReadPeriodRef</code> und <code>CanMainFunctionWritePeriodRef</code> (jeweils <code>0..1</code>) koppeln über Referenzbeziehungen die periodische Abarbeitung normativ an ein oder mehrere Hardware-Objekte (<code>CanHardwareObject</code> mit Multiplizität <code>1..*</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-8b9aab2dc98ed3c4", "to": "FIG-bf0f50958e573c82", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>CanLPduReceiveCalloutFunction</strong> (:FunctionNameDef): Als neuer Konfigurationsparameter unter <code>CanGeneral</code> ergänzt (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, Rolle <code>+parameter</code>).</li>\n<li><strong>CanMainFunctionReadPeriod</strong> / <strong>CanMainFunctionWritePeriod</strong>: Multiplizität explizit auf <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> festgelegt.</li>\n<li><strong>CanMainFunctionReadPeriodRef</strong> (:ReferenceParamDef): Neu hinzugefügt (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, Rolle <code>+reference</code>), referenziert als Ziel (<code>+destination</code>) den Container <code>CanHardwareObject : ParamConfContainerDef</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>).</li>\n<li><strong>CanMainFunctionWritePeriodRef</strong> (:ReferenceParamDef): Neu hinzugefügt (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, Rolle <code>+reference</code>), referenziert als Ziel (<code>+destination</code>) den Container <code>CanHardwareObject : ParamConfContainerDef</code>.</li>\n<li><strong>CanHardwareObject</strong> (:ParamConfContainerDef): Neuer Ziel-Container für die Referenzen <code>CanMainFunctionReadPeriodRef</code> und <code>CanMainFunctionWritePeriodRef</code>.</li>\n<li><strong>CanMainFunctionBusoffPeriod</strong> und <strong>CanMainFunctionWakeupPeriod</strong>: Vom rechten Zweig auf die linke Seite des Containers <code>CanGeneral</code> umpositioniert.</li>\n<li><strong>Diagrammrahmen / Stereotyp</strong>: Rahmentitel <code>object CanDrvGeneral</code> entfernt; Reihenfolge von <code>upperMultiplicity</code> und <code>lowerMultiplicity</code> in den Multiplizitätsangaben teils vertauscht.</li>\n</ul>"}]};
